Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "SQ0!1+4!1,5|30;}2!3+2+0!2'30!1'6#1!2'71#1!2'71#2!1,;3!1,;4!1,;#2!2'716|10;!1,@8!1'A#2!2'?9:!1,@,B!2'>;<!2'>=<!2'>:<!2'?9?!1+2+0!1+2+=$x;R+0$y;R+0!3'D!3+2+=:!1'A#1!3+2+0#2#1!2'E#2#1!2'>#1<$x;R+=D!2,8+=9!2,8+=:!B'H+0+0+0+=+=+='I'A'A'A'?'J19F#2:G!2'30!1'6#2!1'AI!3+2+=J;!2'30!1'6#4!1+U+=!2,\+=9!2,^0+=,B!2,\+=<$j;R+0!4'1$j;R+02!2,8+0!2'71,9$j;R+0$IH;R2vd!6':+03$n;R+0!3+2+0!1,;!1,;#1!2'71!1,;#3!4'<!3+2+057!3+2+=>@!<'C+0+=A'ABC5>!<'F+0+0+=+=,;'A'AE'G4=!<'F+0+0+=+=,;'A'AE'G3;H7@!B'H+0+0+0+=+=+='I'A'A'A'?'J19F6?!<'F+0+0+=+=,;'A'AE'G#2:G&IH0;R!4'K!3+2+0I3K!<'C+0+=A'ABCIJ!2,8+=J3;H#1K&cstr;R!1'L#3!2'M,N!1'A#3&cstr0;R!1'LL!2'M,N!1'AL&__arith;R$__x1;R+=&__wit;R!1,O+P!1+Q+P&__varmap;R!2,R+=#2!1+S+=&__ff;R!7,TM'V+W+W,X!4,Y+=!3,Z+=!3,Z+=!3,[+=NOPP,^1!3,[+=N!3,Z+=OP,^2!2'^3M,X!4'^4#1#3vv!2,8+^5,^6!3+2+^5!2'^7#1#3,^6!3'^8+=,N#2%__x1;R+=!3+2+=!2'>!2'>!2'?9#1<<!2'?9D!1#1!1'A#6I#1!3+2+0!2'30!1'667#1").
Qed.

